  20→**Step 1: Write the session utility**
  21→
  22→Create `backend/app/session.py` with the following:
  23→
  24→```python
  25→import json
  26→import os
  27→import tempfile
  28→from pathlib import Path
  29→
  30→
  31→def truncate_session(session_id: str, user_message_index: int) -> None:
  32→    """Truncate session JSONL file, removing the Nth user query and everything after.
  33→
  34→    Args:
  35→        session_id: The Claude session UUID.
  36→        user_message_index: 0-based index of the user query to truncate from.
  37→
  38→    Raises:
  39→        FileNotFoundError: If the session JSONL file does not exist.
  40→        ValueError: If the user_message_index is out of range.
  41→    """
  42→    session_path = get_session_path(session_id)
  43→    if not session_path.exists():
  44→        raise FileNotFoundError(f"Session file not found: {session_id}")
  45→
  46→    with open(session_path, "r") as f:
  47→        lines = f.readlines()
  48→
  49→    user_query_count = 0
  50→    truncate_at = len(lines)
  51→
  52→    for i, line in enumerate(lines):
  53→        entry = json.loads(line)
  54→        if _is_user_query(entry):
  55→            if user_query_count == user_message_index:
  56→                truncate_at = i
  57→                break
  58→            user_query_count += 1
  59→
  60→    if truncate_at == len(lines):
  61→        raise ValueError(f"User message index {user_message_index} not found in session {session_id}")
  62→
  63→    # Atomic write: write to temp file then rename to prevent corruption
  64→    dir_path = session_path.parent
  65→    with tempfile.NamedTemporaryFile(
  66→        mode="w", dir=dir_path, delete=False, suffix=".jsonl"
  67→    ) as tmp:
  68→        tmp.writelines(lines[:truncate_at])
  69→        tmp_path = tmp.name
  70→    os.replace(tmp_path, session_path)
  71→
  72→
  73→def _is_user_query(entry: dict) -> bool:
  74→    """Check if a JSONL entry is a user query (not a tool result).
  75→
  76→    User queries have type="user" and message.content as a string.
  77→    Tool result entries have message.content as a list of objects.
  78→    """
  79→    return entry.get("type") == "user" and isinstance(
  80→        entry.get("message", {}).get("content"), str
  81→    )
  82→
  83→
  84→def get_session_path(session_id: str) -> Path:
  85→    """Construct path to session JSONL file.
  86→
  87→    The Claude Agent SDK stores sessions at:
  88→    ~/.claude/projects/<encoded-cwd>/<session-id>.jsonl
  89→
  90→    Where <encoded-cwd> replaces "/" with "-" in the current working directory.
  91→    """
  92→    cwd = os.getcwd()
  93→    encoded = cwd.replace("/", "-")
  94→    return Path.home() / ".claude" / "projects" / encoded / f"{session_id}.jsonl"
  95→```
