 220→export async function runAgentEditLoop(
 221→  sessionId: string,
 222→  userMessageIndex: number,
 223→  newMessage: string,
 224→  callbacks: AgentCallbacks,
 225→  signal?: AbortSignal,
 226→): Promise<void> {
 227→  try {
 228→    const response = await fetch('/api/chat/edit', {
 229→      method: 'POST',
 230→      headers: { 'Content-Type': 'application/json' },
 231→      body: JSON.stringify({
 232→        session_id: sessionId,
 233→        user_message_index: userMessageIndex,
 234→        new_message: newMessage,
 235→      }),
 236→      signal,
 237→    });
 238→
 239→    if (!response.ok) {
 240→      const errorText = await response.text();
 241→      callbacks.onError(`Server error: ${errorText}`);
 242→      return;
 243→    }
 244→
 245→    const reader = response.body?.getReader();
 246→    if (!reader) {
 247→      callbacks.onError('No response stream');
 248→      return;
 249→    }
 250→
 251→    const decoder = new TextDecoder();
 252→    let buffer = '';
 253→
 254→    while (true) {
 255→      const { done, value } = await reader.read();
 256→      if (done) break;
 257→
 258→      buffer += decoder.decode(value, { stream: true });
 259→      const lines = buffer.split('\n');
 260→      buffer = lines.pop() ?? '';
 261→
 262→      let eventType = '';
 263→      for (const line of lines) {
 264→        if (line.startsWith('event: ')) {
 265→          eventType = line.slice(7).trim();
 266→        } else if (line.startsWith('data: ')) {
 267→          const data = line.slice(6);
 268→          try {
 269→            const parsed = JSON.parse(data);
 270→            handleSSEEvent(eventType, parsed, callbacks);
 271→          } catch {
 272→            // Skip malformed JSON
 273→          }
 274→          eventType = '';
 275→        }
 276→      }
 277→    }
 278→  } catch (e: unknown) {
 279→    if (signal?.aborted) return;
 280→    const msg = e instanceof Error ? e.message : 'Connection failed';
 281→    callbacks.onError(msg);
 282→  }
 283→}
 284→
 285→export async function deleteAgentMessage(
 286→  sessionId: string,
 287→  userMessageIndex: number,
 288→): Promise<void> {
